insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('profile','profile','Your Name','Cybersecurity engineer focused on LLM and AI application security, AI red teaming and explainable risk assessment','Open to MSc and AI security roles · 2027','I am a final-year BSc (Hons) Cybersecurity and Networks student at the University of East London and the founder of MUK Talent. My work sits where security engineering meets machine learning: I break LLM applications to learn how to defend them, I design guardrails for RAG and agentic systems, and I build risk models that explain their decisions in plain language.
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('experience','exp-muk-talent','Founder & Director','','London · Company no. 16987132','Founded a UK student-recruitment and talent company and built its full digital platform myself: public website, student portal, team workspace, media studio and digital business cards. Designed the authentication, row-level security policies and audit trail on Supabase, and run the security reviews before every release.','Leadership, Secure architecture, Supabase RLS, Node.js, Vercel','MUK Talent (Maghreb UK Talent Ltd)','2025-11-01',null,'','','','',1,true) on conflict (slug) do nothing;
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('experience','exp-cisco-ethical-hacker','Ethical Hacker · Work-Based Learning placement','','Remote · 4 weeks','Completed a structured offensive-security placement: reconnaissance, vulnerability scanning, web and network exploitation, social-engineering simulations and professional penetration-test reporting in guided lab environments.','Penetration testing, Nmap, Metasploit, OWASP Top 10, Reporting','Cisco Networking Academy · Skills for All','2026-02-08','2026-03-08','','','','',2,true) on conflict (slug) do nothing;
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('experience','exp-ai-security-research','Independent AI Security Researcher','','Self-directed','Build and publish small, reproducible labs on LLM attack and defence: automated jailbreak and prompt-injection test suites, retrieval-poisoning experiments on RAG pipelines and policy enforcement for AI agents. Results are documented as short write-ups with mitigations.','Red teaming, garak, PyRIT, LangChain, Evaluation','Open-source labs','2025-09-01',null,'','','','',3,true) on conflict (slug) do nothing;
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('education','edu-uel-bsc','BSc (Hons) Cybersecurity and Networks','','Expected First Class Honours','Network security, ethical hacking, digital forensics, secure software development, cloud security and machine learning for security. Final-year project: AegisGate, an explainable AI network detection and response platform.','Network security, Forensics, Secure development, Machine learning','University of East London','2023-09-01','2026-07-01','','','','',1,true) on conflict (slug) do nothing;
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('education','edu-msc-ai-security','MSc Cybersecurity & Artificial Intelligence (applying)','','Scholarship applications','Planned research focus: adversarial robustness of LLM applications, security of retrieval-augmented and agentic systems, and explainable risk assessment for security operations.','Research, Adversarial ML, AI safety','Target: KAUST · MBZUAI · HBKU · Erasmus Mundus · GKS','2027-09-01',null,'','','','',2,true) on conflict (slug) do nothing;
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('project','aegisgate','AegisGate','AI-driven network detection and response with explainable alerts','AI Security','AegisGate learns the normal behaviour of a network and flags what does not fit. It ingests flow and packet telemetry, scores anomalies with an ensemble of unsupervised models and correlates evidence across hosts and time windows before it raises an alert.
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('project','promptbreaker','PromptBreaker','Automated red-teaming harness for LLM applications','AI Red Teaming','PromptBreaker runs repeatable adversarial test campaigns against chat assistants and LLM-powered APIs. It ships attack packs for direct and indirect prompt injection, jailbreaks, system-prompt leakage, sensitive data disclosure and insecure output handling.
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('project','rag-shield','RAG Shield','Defence-in-depth for retrieval-augmented generation','RAG & Agents','RAG Shield is a reference pipeline that shows how to keep a retrieval-augmented assistant safe. Documents are tagged with access labels at ingestion, so retrieval respects the permissions of the person asking.
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('project','agentgate','AgentGate','Policy firewall for AI agent tool calls','RAG & Agents','AgentGate sits between an AI agent and the tools it can use. Every tool call is checked against declarative policies: which tools, which arguments, how much data and how often. Risky actions pause for human approval.
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('project','clearrisk','ClearRisk','Explainable cyber risk assessment for small organisations','Risk Engineering','ClearRisk turns asset inventories, vulnerability scans and configuration checks into a single risk score per asset and per business process. A gradient-boosted model estimates likelihood and SHAP values explain which factors drive each score.
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('project','ethical-hacker-lab','Penetration Test Report','Full-scope assessment of a simulated SME network','Security Engineering','End-to-end penetration test of a simulated small-business environment: scoping, reconnaissance, vulnerability discovery, exploitation of web and network services and privilege escalation.
insert into public.mt_personal_items (kind,slug,title,subtitle,category,body,tags,issuer,issued_on,expires_on,website_url,repository_url,verification_url,cover_path,sort_order,published) values ('project','muk-talent-platform','MUK Talent Platform','Secure student-recruitment platform built end to end','Secure Web','Designed and built the complete MUK Talent platform: multilingual public website, student portal, team workspace with media studio and chat, and digital business cards with Apple and Google Wallet passes.
